INSERT INTO "vestigingen" ("id","name","address","city","postal_code","description","description_en","archived_at","created_at","updated_at","image_url") VALUES('ce3bd461f11895258095c5494c23b588','Naamsestraat 29A','Naamsestraat 29A','Leuven','3000',replace('Dit gebouw biedt unieke studentenkamers in het hart van Leuven. Je woont hier op een toplocatie, op wandelafstand van de universiteit, winkels en het bruisende stadsleven.\n\nHet gebouw beschikt over een gezellige centrale buitenruimte met vijf aparte ingangen die elk toegang geven tot verschillende kamers. Daarnaast is er een recent vernieuwde gemeenschappelijke keuken met televisie, ideaal om samen te koken en te ontspannen.\n\nEr is bovendien een veilige en afgesloten fietsenstalling voorzien.\n\nComfort in elke kamer\n\nAlle kamers zijn uitgerust met:\n\nDubbele beglazing\n\nKotnet (internetverbinding)\n\nParlofoon\n\nAansluitmogelijkheid voor kabeltelevisie\n\nWarm en koud water\n\nDe douches en toiletten zijn gemeenschappelijk en worden netjes onderhouden.','\n',char(10)),NULL,NULL,'2026-02-23 09:55:31','2026-02-23 09:55:31',NULL);
INSERT INTO "vestigingen" ("id","name","address","city","postal_code","description","description_en","archived_at","created_at","updated_at","image_url") VALUES('d51d0e166e3387f845dd7ae64b1490c5','J.P. Minckelersstraat 79','J.P. Minckelersstraat 79','Leuven','3000',replace('Dit gebouw biedt verschillende types studentenkamers in Leuven, afgestemd op diverse woonwensen en budgetten. Je kan kiezen voor een studentenkamer met gedeeld sanitair of voor een studio met privébadkamer voor extra comfort en privacy.\n\nDe residentie is ideaal gelegen vlak bij het centrum van Leuven, op wandelafstand van universiteit, winkels en openbaar vervoer. Tegelijk geniet je hier van een rustige woonomgeving, weg van de drukte van het stadscentrum.\n\nEen perfecte combinatie van centrale ligging en aangenaam wooncomfort voor studenten die een kot willen huren in Leuven.','\n',char(10)),NULL,NULL,'2026-02-23 10:00:25','2026-02-23 10:00:25',NULL);
INSERT INTO "vestigingen" ("id","name","address","city","postal_code","description","description_en","archived_at","created_at","updated_at","image_url") VALUES('637f58e754b17199ea92ac04c79e74da','Dreefstraat 104','Dreefstraat 104',' Heverlee','3001',replace('Nieuwe, moderne en volledig gemeubelde studentenkamers beschikbaar in verschillende oppervlaktes: 12 m², 14 m², 17 m², 18 m², 21 m² en 35 m². Zo vind je steeds een kamer die perfect aansluit bij jouw wensen en budget.\n\nElke kamer biedt hedendaags comfort in een verzorgde en aangename studentenresidentie in Heverlee.\n\nDaarnaast is er een ruime gemeenschappelijke keuken en gezellige living met televisie voorzien, ideaal om samen te koken, studeren of ontspannen met medestudenten.','\n',char(10)),NULL,NULL,'2026-02-23 10:05:34','2026-02-23 10:06:21',NULL);
INSERT INTO "vestigingen" ("id","name","address","city","postal_code","description","description_en","archived_at","created_at","updated_at","image_url") VALUES('04cb31a0552a92bec75648fe4f2a2e32','J.P. Minckelersstraat 104 – 106','J.P. Minckelersstraat 104 – 106','Leuven','3000',replace('Dit gebouw biedt een ruime keuze aan moderne, gemeubelde studentenkamers in Leuven, geschikt voor uiteenlopende woonwensen.\n\nEr zijn nieuwe en ruime duplexkamers met privé-sanitair, beschikbaar in oppervlaktes van 14 m², 16 m², 17 m², 20 m², 21 m², 25 m² en 30 m². Deze kamers combineren comfort en privacy met toegang tot een gemeenschappelijke keuken en gezellige living met televisie.\n\nDaarnaast zijn er dubbele kamers beschikbaar, eventueel geschikt voor twee personen. Deze kamers zijn volledig van elkaar gescheiden en beschikken over eigen sanitair, wat zorgt voor extra privacy en gebruiksgemak.\n\nHet gebouw biedt ook verschillende ruime kamers en studio’s van 21 m² tot 40 m². Bewoners genieten hier van een gemeenschappelijke tuin en een aangename living met televisie, ideaal om te ontspannen of samen te komen met medestudenten.\n\nVoor alle huurders is een veilige fietsenstalling voorzien.','\n',char(10)),NULL,NULL,'2026-02-23 10:07:57','2026-02-23 10:07:57',NULL);
